4c764f-50cd-45ed-b4f4-db94ce27cc27',false,'49261','31193'),('4a4981f1-ec07-496b-8663-ea095b2cebe7',true,'49262','43442'),('8f3f24ac-853d-4093-8c10-223466d793fd',true,'49264','43442'),('1ff99021-3d59-4700-9e48-bed63e4afb60',true,'49265','43442'),('2f9c6321-8e3c-4717-b99a-08c8ad3ce78f',true,'49266','31064'),('b6f2f3bc-4bbb-46c2-9449-d7de5fe7f757',true,'49267','38258')) AS v(unit_id, prim, fo, mgr)
JOIN public.candidates f ON f.employee_code = v.fo
JOIN public.candidates m ON m.employee_code = v.mgr
WHERE f.id <> m.id
ON CONFLICT (candidate_id, manager_id) DO UPDATE SET is_primary = EXCLUDED.is_primary, unit_id = COALESCE(public.candidate_reporting_managers.unit_id, EXCLUDED.unit_id);
COMMIT;
INSERT INTO public.candidate_reporting_managers (candidate_id, manager_id, unit_id, is_primary, source)
SELECT f.id, m.id, NULL, true, 'fo_client_mapping'
FROM public.candidates f, public.candidates m
WHERE f.employee_code='49263' AND m.employee_code='31064'
ON CONFLICT (candidate_id, manager_id) DO NOTHING;
